 s=s.replace('var began=process.TotalProcessorTime;var input=state.Input;', 'if(cheapTail&&operation!="proposal-ranking"&&++tailSeedOrdinal%2==0){HeldContinuationRequests++;var held=state.Input.Pending.LastOrDefault()?.Action??state.Input.Active;return new(new(state.Input.Time,held,FreeActionSafety.Uncertain,false,Array.Empty<FreeLearningCandidate>(),0,0),0); }\n        FullK1Executions++;var began=process.TotalProcessorTime;var input=state.Input;')
